{
  "name": "opencode-novel-tools",
  "version": "0.1.0",
  "description": "OpenCode 小说创作工具插件",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc && cp -r src/template dist/template",
    "dev": "tsc --watch",
    "clean": "rm -rf dist",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ai",
    "plugin",
    "novel",
    "writing",
    "小说",
    "写作"
  ],
  "author": "piaoxianguo",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/piaoxianguo/opencode-novel-tools.git"
  },
  "homepage": "https://github.com/piaoxianguo/opencode-novel-tools#readme",
  "bugs": {
    "url": "https://github.com/piaoxianguo/opencode-novel-tools/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.49",
    "gray-matter": "^4.0.3"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  }
}

